# ---------------------------------------------------------------- ch10 cell cycle

STAGES = [  # stage, chromosomes as multiple of 2n, DNA content as multiple of 2C
    ('G1 phase', 1, 1), ('S phase (end)', 1, 2), ('G2 phase', 1, 2), ('mitotic metaphase', 1, 2), ('mitotic anaphase', 2, 2),
    ('each daughter cell after mitotic telophase and cytokinesis', 1, 1), ('meiotic metaphase I', 1, 2), ('each cell after telophase I', 0.5, 1),
    ('meiotic metaphase II (each cell)', 0.5, 1), ('meiotic anaphase II (each cell)', 1, 1), ('each gamete or meiotic product', 0.5, 0.5),
]
ORGS = [('an onion root tip cell', 16), ('a human somatic cell', 46), ('a pea plant cell', 14), ('a maize cell', 20), ('a dog cell', 78), ('a rice cell', 24)]


def chrom_count(r):
    org, n2 = r.choice(ORGS)
    st, k, _ = r.choice(STAGES)
    good = int(n2 * k)
    cands = [n2 // 2, n2, 2 * n2, 4 * n2]
    wrong = [str(c) for c in cands if c != good][:3]
    return mcq(f'{cap(org)} has {n2} chromosomes (2n = {n2}). How many chromosomes are present in {st}?', str(good), wrong,
               f'{cap(st)}: {good} chromosomes (counting centromeres).', r)


def dna_content(r):
    c = r.choice([2, 4, 5, 6, 8, 10, 12])
    st, _, k = r.choice(STAGES)
    good = c * k
    lab = lambda x: (f'{x:g} pg')
    cands = [c / 2, c, 2 * c, 4 * c]
    wrong = [lab(x) for x in cands if x != good][:3]
    return mcq(f'A diploid cell in G1 has {c} pg of DNA (2C = {c} pg). What is the DNA content of {st}?', lab(good), wrong,
               f'DNA doubles in S phase (2C → 4C) and halves at each division; {st}: {lab(good)}.', r)


def chrom_dna_written(r):
    org, n2 = r.choice(ORGS)
    a, b = r.sample(STAGES, 2)
    return {'stem': f'{cap(org)} has 2n = {n2}. Give the number of chromosomes and the DNA content (in terms of C, where the G1 cell has 2C) in (i) {a[0]} and (ii) {b[0]}.',
            'answer': f'(i) {int(n2 * a[1])} chromosomes, {int(a[2] * 2) if (a[2] * 2) % 1 == 0 else a[2] * 2}C; (ii) {int(n2 * b[1])} chromosomes, {int(b[2] * 2) if (b[2] * 2) % 1 == 0 else b[2] * 2}C',
            'key': '½ mark for each chromosome number and each DNA content; chromosome number doubles only at anaphase (centromere split); DNA doubles in S phase and halves at each cytokinesis.',
            'marks': 2}


